      return next.isNextEdgeFromPolygon;
    }
    if (isPointInLine(next, next.previous, a) && isPointInLine(next, next.previous, b)) {
      return next.previous.isNextEdgeFromPolygon;
    }
    next = next.next;
  } while (next != a);
